/*
 * pvr_pds_render_gen.c -- the PDS programs of a TA + 3D render on the
 * BXS-4-64 (BVNC 36.53.104.796), generated by Mesa 26.2.1's PDS generators
 * (third_party/mesa-26.2.1/src/imagination/vulkan/pds/pvr_pds.c, compiled by
 * driver/compat/pvr_mesa_pds.c).
 *
 * What is ours here is only which Mesa program each of these is, how it is
 * set up, and the checks a caller may get wrong; the encodings are Mesa's
 * (and the coefficient iterators' words csbgen's, rogue/pds.xml). Mesa
 * writes a program's data and code into one 16-byte aligned staging buffer;
 * the callers here take them as two arrays, so each program is generated
 * into a staging buffer and copied out.
 *
 * The API (pvr_pds_render_gen.h) is unchanged from the hand-written encoder
 * this file replaced; tools/hostharness proves the words equal.
 */

#include <stdint.h>
#include <stddef.h>
#include <string.h>

#include "pvr_mesa.h"
#include "pvr_pds_render_gen.h"
#include "pvr_pds_pixel_event_gen.h"

/* The DOUTU temps field is six bits of four-temp blocks and WRAPS rather
 * than saturating (Mesa's pvr_pds_setup_doutu() only asserts), so a shader
 * above PVR_PDS_DOUTU_MAX_TEMPS would be told it needs none: refused here. */
_Static_assert(PVR_PDS_DOUTU_MAX_TEMPS ==
                  PVR_ROGUE_PDSINST_DOUT_FIELDS_DOUTU_TEMPS_MASK *
                     PVR_ROGUE_PDSINST_DOUT_FIELDS_DOUTU_SRC0_TEMPS_ALIGNSIZE,
               "PVR_PDS_DOUTU_MAX_TEMPS is the DOUTU temps field's limit");

/* Mesa's ROGUE_PDS_FIXED_PIXEL_SHADER_DATA_SIZE (pvr_pds.c, file-local). */
#define PDS_KICK_USC_DATA_DW 8u

/* Staging buffers: Mesa asserts 16-byte alignment (PDS_ROGUE_TA_STATE_PDS_
 * ADDR_ALIGNSIZE) and writes data then code. Sized for the largest program
 * the callers may ask for: PVR_PDS_VERTEX_MAX_STREAMS streams and the id
 * block, PVR_PDS_COEFF_MAX_VARYINGS varyings plus Z, W and the point
 * coordinate, PVR_PDS_DMA_MAX_KICKS kicks. */
#define PDS_STAGING_DW 512u

/* ========================================================================= *
 * Vertex fetch: Mesa's pvr_pds_vertex_shader(), one stream per attribute
 * with one non-repeating element each (pvr_clear.c
 * pvr_pds_clear_vertex_shader_program_init_base() for the clear rect),
 * gl_VertexID / gl_InstanceID through iterate_vtx_id / iterate_instance_id.
 * ========================================================================= */
static int vertex_program(uint64_t vs_usc_exec_offset, uint32_t vs_temps,
                          const struct pvr_pds_render_stream *streams, uint32_t num_streams,
                          int has_slc_mcu_cache_controls, uint32_t vertex_id_reg,
                          uint32_t instance_id_reg, uint32_t *data_out, uint32_t *code_out,
                          struct pvr_pds_render_vertex_info *info, uint32_t fixed_vtxin_dw)
{
   uint32_t vtxin_dw = 0;
   const struct pvr_device_info *dev_info = pvr_mesa_dev_info(has_slc_mcu_cache_controls);
   _Alignas(16) uint32_t staging[PDS_STAGING_DW];
   struct pvr_pds_vertex_shader_program program;

   if (num_streams > PVR_PDS_VERTEX_MAX_STREAMS || vs_temps > PVR_PDS_DOUTU_MAX_TEMPS)
      return -1;

   memset(&program, 0, sizeof(program));
   pvr_pds_setup_doutu(&program.usc_task_control, vs_usc_exec_offset, vs_temps,
                       ROGUE_PDSINST_DOUTU_SAMPLE_RATE_INSTANCE, false);
   program.num_streams = num_streams;
   for (uint32_t s = 0; s < num_streams; s++) {
      const struct pvr_pds_render_stream *st = &streams[s];
      uint32_t dma_dw = (st->dma_size + 3u) / 4u;

      /* The DDMAD burst size is eight bits of dwords. */
      if (dma_dw == 0 || dma_dw > PVR_ROGUE_PDSINST_DDMAD_FIELDS_BSIZE_UPPER)
         return -1;
      if (st->dst_reg + dma_dw > vtxin_dw)
         vtxin_dw = st->dst_reg + dma_dw;
      program.streams[s].instance_data = st->per_instance != 0;
      program.streams[s].address = st->address;
      program.streams[s].stride = st->stride;
      program.streams[s].num_elements = 1;
      program.streams[s].elements[0].size = st->dma_size;
      program.streams[s].elements[0].reg = (uint16_t)st->dst_reg;
   }
   if (vertex_id_reg != PVR_PDS_NO_ID_REG) {
      program.iterate_vtx_id = true;
      program.vtx_id_register = vertex_id_reg;
      if (vertex_id_reg + 1 > vtxin_dw)
         vtxin_dw = vertex_id_reg + 1;
   }
   if (instance_id_reg != PVR_PDS_NO_ID_REG) {
      program.iterate_instance_id = true;
      program.instance_id_register = instance_id_reg;
      if (instance_id_reg + 1 > vtxin_dw)
         vtxin_dw = instance_id_reg + 1;
   }

   pvr_pds_vertex_shader(&program, NULL, PDS_GENERATE_SIZES, dev_info);
   if (program.data_size + program.code_size > PDS_STAGING_DW)
      return -1;
   memset(staging, 0, sizeof(staging));
   pvr_pds_vertex_shader(&program, staging, PDS_GENERATE_DATA_SEGMENT, dev_info);
   pvr_pds_vertex_shader(&program, &staging[program.data_size], PDS_GENERATE_CODE_SEGMENT,
                         dev_info);
   memcpy(data_out, staging, program.data_size * sizeof(uint32_t));
   memcpy(code_out, &staging[program.data_size], program.code_size * sizeof(uint32_t));

   if (info) {
      info->data_size_dw = program.data_size;
      info->code_size_dw = program.code_size;
      info->temps_used = program.temps_used;
      /* VDM_STATE5's units (vdm.xml): the PDS data and temps in 16 bytes,
       * the vertex inputs in 16 bytes (pvr_arch_cmd_buffer.c,
       * pvr_emit_dirty_vdm_state). */
      info->vdm_pds_data_size_units =
         DIV_ROUND_UP(program.data_size * 4u, ROGUE_VDMCTRL_VDM_STATE5_VS_PDS_DATA_SIZE_UNIT_SIZE);
      info->vdm_pds_temp_size_units =
         DIV_ROUND_UP(program.temps_used * 4u, ROGUE_VDMCTRL_VDM_STATE5_VS_PDS_TEMP_SIZE_UNIT_SIZE);
      info->vdm_usc_unified_size_units =
         DIV_ROUND_UP((fixed_vtxin_dw ? fixed_vtxin_dw : vtxin_dw) * 4u, ROGUE_VDMCTRL_VDM_STATE5_VS_USC_UNIFIED_SIZE_UNIT_SIZE);
   }
   return 0;
}

int pvr_pds_render_clear_vertex_program(uint64_t vs_usc_exec_offset,
                                        uint32_t vs_temps,
                                        uint64_t vertex_buf_addr,
                                        uint32_t vertex_stride,
                                        uint32_t vertex_dma_size,
                                        uint32_t vertex_dst_reg,
                                        int has_slc_mcu_cache_controls,
                                        uint32_t *data_out,
                                        uint32_t *code_out,
                                        struct pvr_pds_render_vertex_info *info)
{
   const struct pvr_pds_render_stream st = {
      .address = vertex_buf_addr,
      .stride = vertex_stride,
      .dma_size = vertex_dma_size,
      .dst_reg = vertex_dst_reg,
   };

   if (!data_out || !code_out)
      return -1;
   /* The clear shader's inputs are the PVR_CLEAR_VERTEX_COORDINATES floats,
    * whatever the DMA moves. */
   return vertex_program(vs_usc_exec_offset, vs_temps, &st, 1, has_slc_mcu_cache_controls,
                         PVR_PDS_NO_ID_REG, PVR_PDS_NO_ID_REG, data_out, code_out, info,
                         PVR_CLEAR_VERTEX_COORDINATES);
}

int pvr_pds_render_vertex_program(uint64_t vs_usc_exec_offset,
                                  uint32_t vs_temps,
                                  const struct pvr_pds_render_stream *streams,
                                  uint32_t num_streams,
                                  int has_slc_mcu_cache_controls,
                                  uint32_t *data_out,
                                  uint32_t *code_out,
                                  struct pvr_pds_render_vertex_info *info)
{
   return pvr_pds_render_vertex_program_ids(vs_usc_exec_offset, vs_temps, streams, num_streams,
                                            has_slc_mcu_cache_controls, PVR_PDS_NO_ID_REG,
                                            PVR_PDS_NO_ID_REG, data_out, code_out, info);
}

int pvr_pds_render_vertex_program_ids(uint64_t vs_usc_exec_offset,
                                      uint32_t vs_temps,
                                      const struct pvr_pds_render_stream *streams,
                                      uint32_t num_streams,
                                      int has_slc_mcu_cache_controls,
                                      uint32_t vertex_id_reg,
                                      uint32_t instance_id_reg,
                                      uint32_t *data_out,
                                      uint32_t *code_out,
                                      struct pvr_pds_render_vertex_info *info)
{
   /* No streams is legal: a vertex shader that builds its geometry from
    * gl_VertexID reads no attribute at all (Qt Quick 3D's post-processing
    * passes draw their full-screen triangle that way). */
   if (!data_out || !code_out || (num_streams > 0 && !streams))
      return -1;
   return vertex_program(vs_usc_exec_offset, vs_temps, streams, num_streams,
                         has_slc_mcu_cache_controls, vertex_id_reg, instance_id_reg, data_out,
                         code_out, info, 0);
}

/* ========================================================================= *
 * Fragment kick: Mesa's pvr_pds_kick_usc() (pvr_arch_pipeline.c
 * pvr_pds_fragment_program_create): one DOUTU, the data segment the fixed
 * eight dwords, of which the DOUTU source takes two.
 * ========================================================================= */
int pvr_pds_render_kick_usc_program(uint64_t fs_usc_exec_offset,
                                    uint32_t fs_temps,
                                    uint32_t sample_rate,
                                    uint32_t *data_out,
                                    uint32_t *code_out,
                                    struct pvr_pds_render_kick_usc_info *info)
{
   _Alignas(16) uint32_t staging[PDS_KICK_USC_DATA_DW + 4];
   struct pvr_pds_kickusc_program program;

   if (!data_out || !code_out || fs_temps > PVR_PDS_DOUTU_MAX_TEMPS)
      return -1;

   memset(&program, 0, sizeof(program));
   memset(staging, 0, sizeof(staging));
   pvr_pds_setup_doutu(&program.usc_task_control, fs_usc_exec_offset, fs_temps, sample_rate,
                       false);
   pvr_pds_kick_usc(&program, staging, 0, false, PDS_GENERATE_CODEDATA_SEGMENTS);
   memcpy(data_out, staging, program.data_size * sizeof(uint32_t));
   memcpy(code_out, &staging[program.data_size], program.code_size * sizeof(uint32_t));

   if (info) {
      info->data_size_dw = program.data_size;
      info->code_size_dw = program.code_size;
      info->doutu_offset = program.doutu_offset;
   }
   return 0;
}

/* ========================================================================= *
 * Common-store DMA: Mesa's pvr_pds_pixel_shader_uniform_texture_data() /
 * _code() with texture DMA kicks only (pvr_blit.c's clear-attachment colour
 * upload is the one-kick case), each kick's control word from
 * pvr_pds_encode_dma_burst().
 * ========================================================================= */
static int dma_program(const struct pvr_pds_dma_kick *kicks, uint32_t num_kicks,
                       int has_slc_mcu_cache_controls, uint32_t *data_out, uint32_t *code_out,
                       struct pvr_pds_render_color_upload_info *info)
{
   const struct pvr_device_info *dev_info = pvr_mesa_dev_info(has_slc_mcu_cache_controls);
   _Alignas(16) uint32_t data[3 * PVR_PDS_DMA_MAX_KICKS + 4];
   _Alignas(16) uint32_t code[PVR_PDS_DMA_MAX_KICKS + 4];
   struct pvr_pds_pixel_shader_sa_program program;

   if (!data_out || !code_out || !kicks || num_kicks == 0 || num_kicks > PVR_PDS_DMA_MAX_KICKS)
      return -1;

   pvr_pds_pixel_shader_sa_initialize(&program);
   program.num_texture_dma_kicks = num_kicks;
   for (uint32_t k = 0; k < num_kicks; k++) {
      if (kicks[k].dwords == 0)
         return -1;
      pvr_pds_encode_dma_burst(&program.texture_dma_control[k], &program.texture_dma_address[k],
                               kicks[k].dest_offset, kicks[k].dwords, kicks[k].address, false,
                               dev_info);
   }
   memset(data, 0, sizeof(data));
   memset(code, 0, sizeof(code));
   pvr_pds_pixel_shader_uniform_texture_data(&program, data, PDS_GENERATE_DATA_SEGMENT, false,
                                             dev_info);
   pvr_pds_pixel_shader_uniform_texture_code(&program, code, PDS_GENERATE_CODE_SEGMENT);
   memcpy(data_out, data, program.data_size * sizeof(uint32_t));
   memcpy(code_out, code, program.code_size * sizeof(uint32_t));

   if (info) {
      info->data_size_dw = program.data_size;
      info->code_size_dw = program.code_size;
      info->temps_used = program.temps_used;
   }
   return 0;
}

int pvr_pds_render_color_upload_program(uint64_t color_buf_addr,
                                        uint32_t dma_dword_count,
                                        uint32_t dest_offset,
                                        int has_slc_mcu_cache_controls,
                                        uint32_t *data_out,
                                        uint32_t *code_out,
                                        struct pvr_pds_render_color_upload_info *info)
{
   const struct pvr_pds_dma_kick kick = {
      .address = color_buf_addr,
      .dwords = dma_dword_count,
      .dest_offset = dest_offset,
   };

   return dma_program(&kick, 1, has_slc_mcu_cache_controls, data_out, code_out, info);
}

int pvr_pds_render_dma_program(const struct pvr_pds_dma_kick *kicks,
                               uint32_t num_kicks,
                               int has_slc_mcu_cache_controls,
                               uint32_t *data_out,
                               uint32_t *code_out,
                               struct pvr_pds_render_color_upload_info *info)
{
   return dma_program(kicks, num_kicks, has_slc_mcu_cache_controls, data_out, code_out, info);
}

/* ========================================================================= *
 * Coefficient loading: Mesa's pvr_pds_coefficient_loading() over one DOUTI
 * iterator word per iterated value (csbgen PDSINST_DOUT_FIELDS_DOUTI_SRC),
 * in the order and with the offsets pvr_arch_pipeline.c
 * (pvr_graphics_pipeline_setup_fragment_coeff_program) gives them:
 * [Z if used] [W if used] [the point coordinate if used] then the varyings.
 *
 * Z (gl_FragCoord.z) and W are 1D GOURAUD iterators of the stored position
 * components; the TE stores Z after W when both are there (f32/f16 offset 2
 * with W, 0 without). The point coordinate is one 2D GOURAUD iterator with
 * pointsprite set and no offset (the TA makes (s, t) across the sprite), and
 * takes two coefficient sets. Each scalar component of a varying takes one
 * four-dword coefficient set; its offset is its index into the stored vertex
 * (the VS output vector less the position components the TE does not store:
 * x and y always, z and w when unused), counted in half dwords
 * ((vtxout - 2 - !z - !w) * 2 in Mesa's terms).
 * ========================================================================= */
static uint32_t douti(enum ROGUE_PDSINST_DOUTI_SHADEMODEL shademodel, bool pointsprite,
                      enum ROGUE_PDSINST_DOUTI_SIZE size, bool perspective, uint32_t offset)
{
   const struct ROGUE_PDSINST_DOUT_FIELDS_DOUTI_SRC v = {
      .shademodel = shademodel,
      .pointsprite = pointsprite,
      .size = size,
      .perspective = perspective,
      .f32_offset = offset,
      .f16_offset = offset,
   };
   uint32_t w;

   ROGUE_PDSINST_DOUT_FIELDS_DOUTI_SRC_pack(&w, &v);
   return w;
}

int pvr_pds_render_coeff_program(int uses_w,
                                 int uses_z,
                                 int uses_pntc,
                                 const struct pvr_pds_coeff_varying *varyings,
                                 uint32_t num_varyings,
                                 uint32_t *data_out,
                                 uint32_t *code_out,
                                 struct pvr_pds_coeff_info *info)
{
   /* pvr_pds_coefficient_loading_program is large (four arrays of 128). */
   static struct pvr_pds_coeff_loading_program program;
   _Alignas(16) uint32_t staging[PDS_STAGING_DW];
   /* Position components the TE stores ahead of the user varyings. */
   const uint32_t pos_stored = 2u + (uses_z ? 1u : 0u) + (uses_w ? 1u : 0u);
   uint32_t n = 0, set = 0;

   if (!data_out || !code_out || num_varyings > PVR_PDS_COEFF_MAX_VARYINGS)
      return -1;

   memset(&program, 0, sizeof(program));
   if (uses_z) {
      program.FPU_iterators[n] = douti(ROGUE_PDSINST_DOUTI_SHADEMODEL_GOURUAD, false,
                                       ROGUE_PDSINST_DOUTI_SIZE_1D, false, uses_w ? 2u : 0u);
      program.destination[n++] = set;
      set += 1;
   }
   if (uses_w) {
      program.FPU_iterators[n] = douti(ROGUE_PDSINST_DOUTI_SHADEMODEL_GOURUAD, false,
                                       ROGUE_PDSINST_DOUTI_SIZE_1D, false, 0);
      program.destination[n++] = set;
      set += 1;
   }
   if (uses_pntc) {
      program.FPU_iterators[n] = douti(ROGUE_PDSINST_DOUTI_SHADEMODEL_GOURUAD, true,
                                       ROGUE_PDSINST_DOUTI_SIZE_2D, false, 0);
      program.destination[n++] = set;
      set += 2;
   }
   for (uint32_t v = 0; v < num_varyings; v++) {
      const struct pvr_pds_coeff_varying *cv = &varyings[v];
      enum ROGUE_PDSINST_DOUTI_SHADEMODEL shade = ROGUE_PDSINST_DOUTI_SHADEMODEL_FLAT_VERTEX0;
      bool persp = false;
      uint32_t off;

      if (cv->components == 0 || cv->components > 4 || cv->vtxout_off < 4)
         return -1;
      if (cv->interp == PVR_PDS_COEFF_SMOOTH || cv->interp == PVR_PDS_COEFF_NPC)
         shade = ROGUE_PDSINST_DOUTI_SHADEMODEL_GOURUAD;
      if (cv->interp == PVR_PDS_COEFF_SMOOTH)
         persp = true;
      /* vtxout_off counts from the start of the VS output vector (gl_Position
       * at 0..3). The offset fields are eight bits; the previous encoder kept
       * the low eight bits of a larger one, and so does this. */
      off = ((cv->vtxout_off - 4u + pos_stored - 2u) * 2u) & 0xffu;
      program.FPU_iterators[n] = douti(shade, false, (enum ROGUE_PDSINST_DOUTI_SIZE)(cv->components - 1u),
                                       persp, off);
      program.destination[n++] = set;
      set += cv->components;
   }
   program.num_fpu_iterators = n;
   program.z_iterator = ~0u;

   if (n == 0) {
      if (info)
         memset(info, 0, sizeof(*info));
      return 0;
   }

   memset(staging, 0, sizeof(staging));
   pvr_pds_coefficient_loading(&program, staging, PDS_GENERATE_CODEDATA_SEGMENTS);
   memcpy(data_out, staging, program.data_size * sizeof(uint32_t));
   memcpy(code_out, &staging[program.data_size], program.code_size * sizeof(uint32_t));

   if (info) {
      info->data_size_dw = program.data_size;
      info->code_size_dw = program.code_size;
      info->coeff_dwords = set * 4u;
      /* TA_STATE_PDS_SIZEINFO1 (ppp.xml): pds_varyingsize in units of four
       * dwords, usc_varyingsize in units of sixteen. */
      info->pds_varyingsize =
         DIV_ROUND_UP(program.data_size, ROGUE_TA_STATE_PDS_SIZEINFO1_PDS_VARYINGSIZE_UNIT_SIZE);
      info->usc_varyingsize =
         DIV_ROUND_UP(set * 4u, ROGUE_TA_STATE_PDS_SIZEINFO1_USC_VARYINGSIZE_UNIT_SIZE);
   }
   return 0;
}
